<?php
if (!defined('WHMCS')) die('Direct access denied');require_once __DIR__.'/bootstrap.php';
use CloudHost247\Currency\Services\CurrencyRepository;use CloudHost247\Currency\Services\UpdateEngine;use CloudHost247\Currency\Support\HttpClient;use CloudHost247\Foundation\Support\Logger;
add_hook('AfterCronJob',1,function(){try{$r=new CurrencyRepository();$s=$r->settings();$last=(string)($s['last_cron_attempt_at']??'');$due=!$last||time()-strtotime($last)>=(int)$s['update_frequency_minutes']*60;if(!$due)return;\WHMCS\Database\Capsule::table('mod_cloudhost247_currency_settings')->updateOrInsert(array('setting_key'=>'last_cron_attempt_at'),array('setting_value'=>date('c'),'updated_at'=>date('Y-m-d H:i:s')));(new UpdateEngine($r,new HttpClient()))->run('cron');\WHMCS\Database\Capsule::table('mod_cloudhost247_currency_settings')->updateOrInsert(array('setting_key'=>'last_cron_at'),array('setting_value'=>date('c'),'updated_at'=>date('Y-m-d H:i:s')));}catch(\Throwable $e){Logger::write('cloudhost247_currency','error','cron.failed',array('message'=>$e->getMessage()));}});
